RANK = {'active': 3, 'idle': 2, 'dnd': 2, 'offline': 0}
def on_device_event(u, dev, evt, epoch):
    d = u.devices.get(dev)
    if d and epoch < d.epoch: return          # stale event from old conn
    apply(u, dev, evt, epoch)
    new = max((x.state for x in live(u.devices)), key=RANK.get, default='offline')
    if new == u.published: cancel(u.timer); return
    delay = 2 if new != 'offline' else 20
    u.timer = schedule(delay, lambda: commit(u, new))
def commit(u, new):
    if aggregate(u) != new: return
    u.version += 1; u.published = new
    if new == 'offline': last_seen.write(u.uid, now())
    if not settings(u).appear_offline: bus.publish(f'presence:{u.uid}', (new, u.version))

wheel = [set() for _ in range(64)]   # 1 s slots
def renew(dev, ttl):
    wheel[dev.slot].discard(dev)
    dev.expiry = now() + ttl
    dev.slot = int(dev.expiry) % 64; wheel[dev.slot].add(dev)
def tick():
    for dev in list(wheel[int(now()) % 64]):
        if dev.expiry <= now(): on_device_event(dev.user, dev.id, 'disconnect_unclean', dev.epoch)

def subscribe(conn, uids):
    for uid in uids[:CAP - len(conn.watching)]:
        if not watchers[uid]: bus.subscribe(f'presence:{uid}')
        watchers[uid].add(conn); conn.watching.add(uid)
def on_bus_message(uid, state, v):
    for conn in watchers[uid]: conn.pending[uid] = (state, v)  # keep latest only
def flush():  # every 250 ms
    for conn in dirty: conn.send({'op': 'presence_batch', 'items': conn.pending}); conn.pending = {}
